from canvasapi import Canvas

def get_courses(canvas_url):
    '''
    Canvas API'yi kullanarak bir canvas örneğindeki tüm kursları elde edin.
    @param canvas_url: Canvas örneğinin URL'si.
    @return: O canvas örneğindeki kursların bir listesi.
    '''
canvas = Canvas(canvas_url, 'your_canvas_api_key')
courses = canvas.get_courses()
